def test_cancel_before_start_raises_value_error():
    from datetime import datetime

    class DummySubscription:
        def __init__(self, start):
            self.start = start
            self.cancelled_on = None

        def cancel(self, when):
            if self.cancelled_on is not None:
                raise RuntimeError("already cancelled")
            if when < self.start:
                raise ValueError("cannot cancel before the start date")
            self.cancelled_on = when

    sub = DummySubscription(start=datetime(2026, 1, 1))
    with pytest.raises(ValueError, match="cannot cancel before the start date"):
        sub.cancel(when=datetime(2025, 12, 31))
